```cpp
Error Name::ReadName(const Message &aMessage, uint16_t &aOffset, char *aNameBuffer, uint16_t aNameBufferSize)
{
    Error         error;
    LabelIterator iterator(aMessage, aOffset);
    bool          firstLabel = true;
    uint8_t       labelLength;

    while (true)
    {
        error = iterator.GetNextLabel();

        switch (error)
        {
        case kErrorNone:

            if (!firstLabel)
            {
                *aNameBuffer++ = kLabelSeparatorChar;
                aNameBufferSize--;

                // No need to check if we have reached end of the name buffer
                // here since `iterator.ReadLabel()` would verify it.
            }

            labelLength = static_cast<uint8_t>(Min(static_cast<uint16_t>(kMaxLabelSize), aNameBufferSize));
            SuccessOrExit(error = iterator.ReadLabel(aNameBuffer, labelLength, /* aAllowDotCharInLabel */ firstLabel));
            aNameBuffer += labelLength;
            aNameBufferSize -= labelLength;
            firstLabel = false;
            break;

        case kErrorNotFound:
            // We reach the end of name successfully. Always add a terminating dot
            // at the end.
            *aNameBuffer++ = kLabelSeparatorChar;
            aNameBufferSize--;
            VerifyOrExit(aNameBufferSize >= sizeof(uint8_t), error = kErrorNoBufs);
            *aNameBuffer = kNullChar;
            aOffset      = iterator.mNameEndOffset;
            error        = kErrorNone;

            OT_FALL_THROUGH;

        default:
            ExitNow();
        }
    }

exit:
    return error;
}
```

So the issue: when the name fills the entire buffer. Let me think about the flow.

The `ReadLabel` function:
```cpp
Error Name::LabelIterator::ReadLabel(char *aLabelBuffer, uint8_t &aLabelLength, bool aAllowDotCharInLabel) const
{
    Error error;

    VerifyOrExit(mLabelLength < aLabelLength, error = kErrorNoBufs);

    SuccessOrExit(error = mMessage.Read(mLabelStartOffset, aLabelBuffer, mLabelLength));
    aLabelBuffer[mLabelLength] = kNullChar;
    aLabelLength               = mLabelLength;
    ...
}
```

So `ReadLabel` requires `mLabelLength < aLabelLength` (i.e., the label length must be strictly less than the buffer length, to leave room for the NUL terminator). If the label exactly fills the buffer, it returns `kErrorNoBufs`.

Now in `ReadName`, when we have a label that exactly fills the remaining buffer:
- `labelLength = Min(kMaxLabelSize, aNameBufferSize)` — this is the remaining buffer size.
- `ReadLabel` checks `mLabelLength < aLabelLength`. If `mLabelLength == aNameBufferSize` (label exactly fills remaining buffer), then `mLabelLength < aLabelLength` is false (since they're equal), so it returns `kErrorNoBufs`.
- `SuccessOrExit(error = iterator.ReadLabel(...))` exits with `kErrorNoBufs`.

So `ReadName` returns `kErrorNoBufs` WITHOUT writing a NUL terminator. The buffer contains the partial name without a NUL terminator.

